 "decisions": [
  {
   "title": "Data moves to the target database (migration)",
   "context": "ORDENES and CUENTAS are VSAM KSDS files accessed through CICS; there is no relational schema or driver to keep.",
   "decision": "Both files become relational tables (orders, accounts) in the target database, with the legacy precision of every field.",
   "consequences": "The files need an initial load. Reads with UPDATE become row locks (SELECT ... FOR UPDATE) inside the transaction."
  },
  {
   "title": "One transaction for the whole payment",
   "context": "PAGOORD works inside a unit of work from begin at line 37 to the SYNCPOINT at line 172. It includes the account rewrite made by PAGODEB through LINK. All rejections happen before any write.",
   "decision": "PayOrder is transactional and covers the debit, the movement registration and the order rewrite. There are no savepoints or rollback points in the legacy, so none are declared. Any exception rolls the whole transaction back.",
   "consequences": "Debit and order update are atomic. If PAGOMOV or the order rewrite fails after the debit, the debit is undone, which the legacy did only implicitly."
  },
  {
   "title": "PAGODEB becomes an internal use case",
   "context": "PAGODEB has its source and works on CUENTAS, which migrates.",
   "decision": "Rules 001-005 are implemented in the DebitAccount use case. PayOrder calls it in-process in the same transaction and maps response codes 10, 20 and 30/40 to the messages of rule 014. It is also exposed over HTTP.",
   "consequences": "No LINK/commarea. The balance check keeps its legacy semantics: a balance equal to the amount is allowed."
  },
  {
   "title": "PAGOMOV stays behind a port",
   "context": "PAGOMOV is not among the inputs and is stubbed in the traces. Its non-zero status is not an output parameter.",
   "decision": "MovementGateway.registerMovement replaces the LINK and returns MOV_NUMERO. The adapter raises a failure on a non-zero status.",
   "consequences": "Replay uses the stub of the trace, and the call is checked with the argument MOV_ORDEN."
  },
  {
   "title": "Amount parsing follows the traces",
   "context": "Rule 012 says NUMVAL(VALORI)/100, but the traces send VALOR as '1500.00' and expect the order of 1500.00 to match.",
   "decision": "The amount is received as text. A value with an explicit decimal point is taken as written. A digits-only value is read with two implied decimals (/100). The comparison with the order value is exact.",
   "consequences": "A reviewer must confirm this at C3. If a digits-only value should be taken as written, the rule changes."
  },
  {
   "title": "Presentation and CICS plumbing are not translated",
   "context": "BMS maps, RECEIVE/SEND, RETURN TRANSID, XCTL, the commarea, PF3/ENTER keys and 'TECLA NO VALIDA' belong to the 3270 conversation.",
   "decision": "The use cases are stateless HTTP operations. Rejections are business errors with stable codes. The menu use case returns the next action instead of an XCTL.",
   "consequences": "CA-ULTIMA-ORDEN is not kept as session state, because it only fed the next screen."
  },
  {
   "title": "Rules exercised by each PAGOORD trace",
   "context": "The rule lists in the trace metadata do not match what each trace really exercises (for example orden_invalida lists RULE-001, which belongs to PAGODEB). The golden master is replayed from traces/PAGOORD.json over the tables ORDENES and CUENTAS.",
   "decision": "By legacy flow: pago_web_exitoso, pago_oficina_exento and pago_web_cuenta_ahorro exercise RULE-007 to RULE-009, RULE-011 to RULE-015 and the debit rules RULE-002 to RULE-005 (RULE-010 only for the office one). orden_invalida: RULE-007. tipo_cuenta_no_permitido: RULE-008. canal_no_permitido: RULE-009. oficina_sin_clave: RULE-010. orden_no_existe and orden_no_pendiente: RULE-011. valor_no_coincide: RULE-012. cuenta_inactiva: RULE-003 and RULE-014. saldo_insuficiente: RULE-004 and RULE-014. cuenta_no_existe: RULE-001 and RULE-014. tipo_no_coincide: RULE-002 and RULE-014. RULE-013 is exercised by every case that reaches the commission calculation.",
   "consequences": "RULE-006 (PAGOMNU) has no trace and is not covered by the replay."
  }
 ],
 "masks": [],
 "infrastructure": [],
 "data_strategy": "migration"
}

