package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.DebitAccountRequest;
import com.bank.payments.adapters.in.rest.DebitAccountResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.port.AccountRepository;
import java.math.BigDecimal;
import java.util.Optional;

/**
 * Application service of DebitAccount (legacy PAGODEB), RULE-001 .. RULE-005.
 *
 * The legacy EVALUATE TRUE is kept in the same order of WHEN branches:
 * not found ('30'), type differs ('40'), not active ('10'), balance below amount ('20'), otherwise debit ('00').
 *
 * UNRESOLVED_DEPENDENCY: the copybook CTAREG is not provided, so the value of the condition CTA-ACTIVA
 * is not known from the source. The value 'A' is the one used by the tests (oracle) for "active".
 */
public class DebitAccountService {

    private static final String ACTIVE_STATUS = "A";

    private final AccountRepository accountRepository;

    public DebitAccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    public DebitAccountResponse execute(DebitAccountRequest request) {
        // EXEC CICS READ FILE('CUENTAS') ... RIDFLD(DEB-CUENTA) UPDATE
        Optional<Account> found = accountRepository.findByNumber(request.accountNumber());

        // WHEN WS-RESP = DFHRESP(NOTFND) -> '30'
        if (found.isEmpty()) {
            throw new BusinessError("ACCOUNT_NOT_FOUND", "30", "Account does not exist");
        }
        Account account = found.get();

        // WHEN CTA-TIPO NOT = DEB-TIPO -> '40' (COBOL alphanumeric comparison: shorter operand padded with spaces)
        if (!sameText(account.accountType(), request.accountType())) {
            throw new BusinessError("ACCOUNT_TYPE_MISMATCH", "40",
                    "Account type does not match the requested type");
        }

        // WHEN NOT CTA-ACTIVA -> '10'
        if (!ACTIVE_STATUS.equals(account.status())) {
            throw new BusinessError("ACCOUNT_INACTIVE", "10", "Account is not active");
        }

        // WHEN CTA-SALDO < DEB-MONTO -> '20' (equal is allowed)
        if (account.balance().compareTo(request.amount()) < 0) {
            throw new BusinessError("INSUFFICIENT_FUNDS", "20", "Insufficient balance");
        }

        // WHEN OTHER -> 1000-DEBITAR
        // SUBTRACT DEB-MONTO FROM CTA-SALDO; REWRITE CUENTAS; DEB-RESP = '00'
        BigDecimal newBalance = account.balance().subtract(request.amount());
        accountRepository.updateBalance(account.accountNumber(), newBalance);

        return new DebitAccountResponse("00", newBalance);
    }

    /** Equality of fixed-length text as COBOL compares it: trailing spaces are not significant, case is. */
    private static boolean sameText(String a, String b) {
        return stripTrailingSpaces(a).equals(stripTrailingSpaces(b));
    }

    private static String stripTrailingSpaces(String value) {
        if (value == null) {
            return "";
        }
        int end = value.length();
        while (end > 0 && value.charAt(end - 1) == ' ') {
            end--;
        }
        return value.substring(0, end);
    }
}
